-- Run the following in the none pipe IRQ stage database

DECLARE @SQL NVARCHAR(MAX)
SET @SQL = 'ALTER DATABASE ' + DB_NAME() + ' SET SINGLE_USER WITH ROLLBACK IMMEDIATE
ALTER DATABASE ' + DB_NAME() + ' SET READ_WRITE
ALTER DATABASE ' + DB_NAME() + ' SET MULTI_USER'

EXECUTE (@SQL)

insert into DomainCatalog (Id, DomainDescr)
select (select max(id) from DomainCatalog) + 1,  'OF Landslide Susceptibility' where not exists (select 1 from DomainCatalog where DomainDescr = 'OF Landslide Susceptibility')


insert into DomainCatalogColXRef(DomainCatalogId, TableName, ColumnName)
select (select Id from DomainCatalog where DomainDescr = 'OF Landslide Susceptibility'), 'OFLandslideSusceptibility','OFLandslideSusceptibility' 
Where Not Exists (Select 1 from DomainCatalogColXRef where TableName = 'OFLandslideSusceptibility' and ColumnName = 'OFLandslideSusceptibility')



